{
  "description": "The creature is a large quadrupedal mammal shown in right-facing profile against a plain light background. Its body, head, legs and tail are covered in dense, long, shaggy brown fur with lighter tan on the muzzle, chest and flank, resembling a bear. On its forehead is a single long, dark brown, glossy, backward-curving horn. Covering most of its back from behind the shoulders to the rump is a large, domed, highly glossy dark reddish-brown structure with transverse ridges and a segmented border, resembling the hardened wing-covers and pronotum of a beetle. It stands on four thick legs ending in clawed paws, with a small furry tail visible at the rear.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like, broad with a slightly elongated muzzle, brown fur with a lighter tan muzzle, a large black nose at the tip, small dark brown eyes in profile, and a slightly open mouth",
      "where": "at the front of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "single thick, smooth, glossy dark brown horn that curves upward and backward to a sharp point, with a slightly ridged base where it meets the fur",
      "where": "protruding from the center of the forehead on top of the head, between and in front of the ears"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, upright ears covered in thick brown fur with slightly darker interiors",
      "where": "on top of the head behind the horn, one slightly behind the other in profile"
    },
    {
      "part": "legs",
      "looks_like": "four thick, columnar, heavily furred legs covered in long shaggy dark brown fur, with lighter fur on the inner chest area above them",
      "where": "two forelegs under the chest and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four broad paws with visible long, curved, light tan to off-white claws on each toe",
      "where": "at the bottom of each leg in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "very small, short, tufted stub of brown fur",
      "where": "at the extreme rear of the body above the hind legs"
    },
    {
      "part": "shell",
      "looks_like": "large, domed, hard and glossy dark reddish-brown carapace with fine transverse ridges and reflective highlights, divided into a smaller anterior section over the shoulders and a larger posterior section over the back",
      "where": "covering the entire dorsal side from just behind the neck to the rump"
    },
    {
      "part": "plates",
      "looks_like": "a continuous border of small, rectangular, brown, scale-like plates each with a shallow oval depression, forming a rim around the lower edge of the shell",
      "where": "along the ventral margin of both sections of the shell where it meets the fur"
    },
    {
      "part": "markings",
      "looks_like": "patches of shorter, lighter cream-tan fur contrasting with the darker brown shaggy fur",
      "where": "on the muzzle, lower chest, and along the side of the belly between the fore and hind legs"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
